package dev.veltraph.client.game;
import java.util.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LocationSignalDerivationCacheTest {
 LocationSignals input(LocationSignalDerivationCache c){return c.signals("Hypixel BungeeCord","mc.hypixel.net","§aSKYBLOCK",List.of("§bThe Garden","Purse: 20"),"Area: Garden",List.of("Players: 1"));}
 @Test void coldAndHotHaveExactOriginalResolutionProvenance(){var c=new LocationSignalDerivationCache();var first=input(c);var expected=GameContextResolver.resolve(LocationSignals.of("Hypixel BungeeCord","mc.hypixel.net","§aSKYBLOCK",List.of("§bThe Garden","Purse: 20"),"Area: Garden",List.of("Players: 1")));assertEquals(expected,c.resolve(first));assertSame(first,input(c));assertSame(c.resolve(first),c.resolve(input(c)));assertEquals(expected,c.resolve(input(c)));}
 @Test void eachCompleteRawChannelChangesTheEntry(){for(int i=0;i<6;i++){var c=new LocationSignalDerivationCache();var before=input(c);String brand=i==0?"Other":"Hypixel BungeeCord",address=i==1?"other.net":"mc.hypixel.net",title=i==2?"BED WARS":"§aSKYBLOCK",footer=i==4?"Area: Hub":"Area: Garden";List<String> rows=i==3?List.of("The Hub"):List.of("§bThe Garden","Purse: 20"),tab=i==5?List.of("Different player"):List.of("Players: 1");var fresh=c.signals(brand,address,title,rows,footer,tab);assertNotSame(before,fresh);assertEquals(GameContextResolver.resolve(LocationSignals.of(brand,address,title,rows,footer,tab)),c.resolve(fresh));}}
 @Test void rowAndTabOrderAreRawInputs(){var c=new LocationSignalDerivationCache();var first=c.signals("Hypixel BungeeCord",null,"SKYBLOCK",List.of("Hub","Garden"),null,List.of("A","B"));var reordered=c.signals("Hypixel BungeeCord",null,"SKYBLOCK",List.of("Garden","Hub"),null,List.of("B","A"));assertNotSame(first,reordered);assertEquals(List.of("Garden","Hub"),reordered.sidebarRowsRaw());assertEquals(GameContextResolver.resolve(LocationSignals.of("Hypixel BungeeCord",null,"SKYBLOCK",List.of("Garden","Hub"),null,List.of("B","A"))),c.resolve(reordered));}
 @Test void formattingAndCaseAreNotNormalizedCacheKeys(){var c=new LocationSignalDerivationCache();var before=c.signals("Hypixel BungeeCord",null,"§aSKYBLOCK",List.of("The Garden"),null,List.of());var changed=c.signals("Hypixel BungeeCord",null,"§bSkyBlock",List.of("the garden"),null,List.of());assertNotSame(before,changed);assertNotEquals(before.sidebarTitleRaw(),changed.sidebarTitleRaw());assertEquals(GameContextResolver.resolve(changed),c.resolve(changed));}
 @Test void mutableCallerListsCannotMutateRetainedTuple(){var c=new LocationSignalDerivationCache();var rows=new ArrayList<>(List.of("The Garden"));var tab=new ArrayList<>(List.of("A"));var before=c.signals("Hypixel BungeeCord",null,"SKYBLOCK",rows,null,tab);rows.set(0,"The Hub");tab.add("B");assertEquals(List.of("The Garden"),before.sidebarRowsRaw());assertEquals(List.of("A"),before.tabLinesRaw());var after=c.signals("Hypixel BungeeCord",null,"SKYBLOCK",rows,null,tab);assertNotSame(before,after);assertEquals(GameContextResolver.resolve(after),c.resolve(after));}
 @Test void nullEmptyAndUnknownPreserveOriginalOutputs(){for(boolean absent:new boolean[]{false,true}){var c=new LocationSignalDerivationCache();List<String> rows=absent?null:Arrays.asList(null,""),tab=absent?null:Arrays.asList("",null);var actual=c.signals(null,null,null,rows,null,tab);assertEquals(GameContextResolver.resolve(LocationSignals.of(null,null,null,rows,null,tab)),c.resolve(actual));assertSame(actual,c.signals(null,null,null,rows,null,tab));}}
 @Test void ABARecomputesAndNeverReusesHistoricalEntry(){var c=new LocationSignalDerivationCache();var a=input(c);c.resolve(a);var b=c.signals("Other",null,"BED WARS",List.of(),null,List.of());assertEquals(GameContext.NONE,c.resolve(b).context());var a2=input(c);assertNotSame(a,a2);assertEquals(GameContextResolver.resolve(a),c.resolve(a2));}
 @Test void reentrantDifferentTupleDoesNotGiveOuterInputLatestResult(){var c=new LocationSignalDerivationCache();var outer=input(c);Supplier<LocationSignals> callback=()->c.signals("Other",null,"BED WARS",List.of(),null,List.of());var inner=callback.get();assertEquals(GameContext.NONE,c.resolve(inner).context());assertEquals(GameContextResolver.resolve(outer),c.resolve(outer));assertSame(inner,c.signals("Other",null,"BED WARS",List.of(),null,List.of()));}
 @Test void unrelatedInputAndErrorsNeverBorrowLatestResolution(){var c=new LocationSignalDerivationCache();var valid=input(c);c.resolve(valid);var unknown=LocationSignals.of(null,null,null,List.of(),null,List.of());assertEquals(GameContextResolver.resolve(unknown),c.resolve(unknown));assertSame(valid,input(c));assertThrows(NullPointerException.class,()->c.resolve(null));assertSame(valid,input(c));}
 @Test void freshlyReadCallbacksStillRunBeforeEveryPureReuse(){var c=new LocationSignalDerivationCache();var log=new ArrayList<String>();Supplier<LocationSignals> read=()->{log.add("brand");String brand="Hypixel BungeeCord";log.add("address");String address="mc.hypixel.net";log.add("title");String title="SKYBLOCK";log.add("rows");var rows=List.of("The Garden");log.add("footer");String footer="Garden";log.add("tab");var tab=List.of("A");return c.signals(brand,address,title,rows,footer,tab);};var first=read.get();c.resolve(first);var second=read.get();c.resolve(second);assertSame(first,second);assertEquals(List.of("brand","address","title","rows","footer","tab","brand","address","title","rows","footer","tab"),log);}
}
